int ntlm_read_message_fields_buffer(NntlmStream *stream, NtlmMessage *message) { if (message->length != 0) { register unsigned int totallength = message->base + message->length; if (Stream_Length(stream) > totallength) return -1; message->data = (unsigned char *) malloc(message->length); if (!message->data) return -1; Stream_SetPosition(stream, message->base); Stream_ReadStream(stream, message->data, message->length); } return 1; }